sql.query:
/**/
SELECT B.ISU_CD ISU_CD, -- 표준코드 SUBSTR(B.ISU_SRT_CD,2) ISU_SRT_CD, -- 단축코드 B.ISU_NM, --한글종목명 B.ISU_ABBRV, --한글종목약명 B.ISU_ENG_NM, --영문종목명 B.LIST_DD, --상장일 DECODE(B.MKT_ID,'STK','KOSPI','KSQ','KOSDAQ','KNX','KONEX') MKT_TP_NM, --시장구분 C.SECUGRP_NM, (SELECT SFMC_CD_NM_LANG (B.SECT_TP_CD, 'SECT_TP_CD', 'ko_KR') MKT_NM FROM DUAL) SECT_TP_NM, --소속부 (SELECT SFMC_CD_NM_LANG (B.KIND_STKCERT_TP_CD, 'KIND_STKCERT_TP_CD', 'ko_KR') FROM DUAL) KIND_STKCERT_TP_NM, -- 주식종류 NVL((SELECT DECODE(A.PAR_TP_CD, 'N', '무액면', NULL) FROM TBLD_ISU_INST A WHERE REP_ISU_CD = B.ISU_CD), B.PARVAL) PARVAL, --액면가 B.LIST_SHRS --상장주식수 FROM TBMC_SPOT_ISU B, TBMC_SECU_GRP C WHERE :basDd BETWEEN B.STRT_DD AND B.END_DD AND B.SECUGRP_ID = C.SECUGRP_ID AND B.SECUGRP_ID IN ('ST', 'MF', 'RT', 'SC', 'IF', 'DR', 'FS') AND :basDd BETWEEN C.STRT_DD AND C.END_DD AND B.MKT_ID IN ('STK', 'KSQ', 'KNX') AND B.MKT_ID = 'KNX' AND :basDd < TO_CHAR(SYSDATE,'YYYYMMDD') AND :basDd >= '20100104' AND 1 = (CASE WHEN :basDd < SFMC_PRE_RECENT_MKTOPN_DD(TO_CHAR(SYSDATE-1, 'YYYYMMDD')) THEN 1 WHEN :basDd = SFMC_PRE_RECENT_MKTOPN_DD(TO_CHAR(SYSDATE-1, 'YYYYMMDD')) AND TO_CHAR(SYSDATE, 'HH24') >= '08' THEN 1 ELSE 0 END) ORDER BY B.ISU_NM
/**/
